/** The mark for an advertised agent kind, or null when a monogram should stand in. */
export function agentIcon(kind: string): AgentIconSpec | null {
  const key = kind.trim().toLowerCase();
  if (!key) return null;
  return AGENT_ICONS[ALIASES[key] ?? key] ?? null;
}
